head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00300_04.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 조회조건 결산일자

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회

	//----W-Craft WebSquare 변환 확인: fn_SrchAcntclsDt----//
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();

    //fn_Search();

};




/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_AsstRevalu.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsDt----//
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 자산재평가 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_AsstRevalu);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.asstRevalu" + "&outputMessageId=FIS_ASST_REVALU" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsDt;
    dts_AsstRevalu.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_AsstRevalu.Reset();
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_AsstRevalu.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_AsstRevalu, "자산재평가", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_AsstRevalu_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_AsstRevalu);
    $c.stf.alert_error(dts_AsstRevalu);
};
scwin.dts_AsstRevalu_OnLoadCompleted = function(rowcount) {
    if (dts_AsstRevalu.errorMsg) {
        alert(dts_AsstRevalu.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_AsstRevalu);
};
